import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {"data": {}, "value_counts": Counter()}

    # Remove None values
    data = {k: v for k, v in data.items() if v is not None}

